<script>
  import { onDestroy, onMount } from "svelte";
  import { createTaskScope } from "./taskManager.js";
  import CopyButton from "./CopyButton.svelte";
  import Select from "./Select.svelte";
  import { createTaskGate, imageInputError, normalizeOcrRectangle, ocrSelectionFromDisplay, validateImageFiles } from "./imageBatch.js";
  import { localizeError, pick } from "./i18n.js";
  import { saveBlobThroughHost } from "./fileSave.js";
  import { cancelOcrModelInstall, getOcrModelStatus, installOcrModels, recognizeNativeOcr, removeOcrModels } from "./nativeOcr.js";

  let { locale = "zh-CN" } = $props(); const t = (zh,en)=>pick(locale,zh,en);
  let file=$state(null);let sourceUrl=$state("");let text=$state("");let confidence=$state(null);let confidenceMin=$state(null);let recognizedLines=$state(0);let resultLines=$state([]);let progress=$state(0);let status=$state("");let busy=$state(false);let error=$state("");let controller=null;
  let quality=$state("auto");let enhance=$state(false);let smartCorrection=$state(true);let layout=$state(true);let showBoxes=$state(true);
  let regionEnabled=$state(false);let selection=$state(null);let imageWidth=$state(0);let imageHeight=$state(0);let imageStage=$state(null);let dragStart=null;let dragPointer=null;
  let models=$state(null);let modelPanelOpen=$state(false);let modelBusy=$state(false);let modelCancelling=$state(false);let modelInstallController=null;let modelSessionId=$state("");let modelProgress=$state(0);let modelStatus=$state("");let modelNoticeTimer=null;let pendingRemove=$state("");
  const qualityOptions=$derived([
    {value:"auto",label:t("智能（推荐）","Smart (recommended)")},
    {value:"accurate",label:t("全量高精度","Full accuracy"),disabled:!models?.accurate?.installed},
    {value:"fast",label:t("快速","Fast")},
  ]);

  const tasks=createTaskGate();
  const recognitionTasks=createTaskScope("image-ocr", "ocr");
  const modelTasks=createTaskScope("image-ocr", "ocr-model");
  onMount(()=>{void refreshModels();});
  onDestroy(()=>{recognitionTasks.dispose();modelTasks.dispose();tasks.cancel();controller?.abort();modelInstallController?.abort();if(modelSessionId)void cancelOcrModelInstall(modelSessionId).catch(()=>{});if(modelNoticeTimer)clearTimeout(modelNoticeTimer);if(sourceUrl)URL.revokeObjectURL(sourceUrl);});
  async function onFile(event){
    const next=event.currentTarget.files?.[0];if(!next)return;
    recognitionTasks.cancel();tasks.cancel();controller?.abort();controller=null;busy=false;
    try {
      validateImageFiles([next],{min:1,max:1,maxFileBytes:20_000_000,maxTotalBytes:20_000_000});
      const dimensions=await readImageDimensions(next);
      file=next;if(sourceUrl)URL.revokeObjectURL(sourceUrl);sourceUrl=URL.createObjectURL(next);text="";confidence=null;resultLines=[];error="";
      imageWidth=dimensions.width;imageHeight=dimensions.height;selection=null;
    } catch(cause) { error=imageInputError(cause,t);event.currentTarget.value=""; }
  }
  function readImageDimensions(input){return new Promise((resolve,reject)=>{const image=new Image();const url=URL.createObjectURL(input);image.onload=()=>{URL.revokeObjectURL(url);resolve({width:image.naturalWidth,height:image.naturalHeight});};image.onerror=()=>{URL.revokeObjectURL(url);reject(Object.assign(new Error("Could not decode image"),{code:"OCR_IMAGE_SIZE"}));};image.src=url;});}
  function progressLabel(stage){return {upload:t("传输图片…","Transferring image…"),decode:t("解码图片…","Decoding image…"),preprocess:t("优化图片尺寸…","Optimizing image size…"),queue:t("等待上一次 OCR 完成…","Waiting for the previous OCR task…"),models:t("加载 OCR 模型…","Loading OCR models…"),detect:t("检测文字区域…","Detecting text regions…"),recognize:t("快速识别文字…","Recognizing text…"),refine:t("高精度复核低置信行…","Refining uncertain lines…"),complete:t("识别完成","Recognition complete")}[stage]||t("处理中…","Processing…");}
  function toggleRegion(event){regionEnabled=event.currentTarget.checked;selection=null;dragStart=null;if(regionEnabled)error="";}
  function pointInStage(event){const box=imageStage?.getBoundingClientRect();if(!box)return null;return{x:event.clientX-box.left,y:event.clientY-box.top,width:box.width,height:box.height};}
  function startSelection(event){if(!regionEnabled||busy||!imageStage)return;const point=pointInStage(event);if(!point)return;event.preventDefault();dragStart=point;dragPointer=event.pointerId;imageStage.setPointerCapture?.(event.pointerId);selection=ocrSelectionFromDisplay(point,point,point.width,point.height,imageWidth,imageHeight);}
  function moveSelection(event){if(dragStart==null||event.pointerId!==dragPointer)return;const point=pointInStage(event);if(!point)return;selection=ocrSelectionFromDisplay(dragStart,point,point.width,point.height,imageWidth,imageHeight);}
  function finishSelection(event){if(event.pointerId!==dragPointer)return;moveSelection(event);imageStage?.releasePointerCapture?.(event.pointerId);dragStart=null;dragPointer=null;}
  function selectionStyle(){if(!selection||!imageWidth||!imageHeight)return "";return `left:${selection.left/imageWidth*100}%;top:${selection.top/imageHeight*100}%;width:${selection.width/imageWidth*100}%;height:${selection.height/imageHeight*100}%`;}
  function boxStyle(bounds){if(!bounds||!imageWidth||!imageHeight)return "";return `left:${bounds.left/imageWidth*100}%;top:${bounds.top/imageHeight*100}%;width:${bounds.width/imageWidth*100}%;height:${bounds.height/imageHeight*100}%`;}
  async function recognize(){if(!file||busy)return;if(!models?.base?.installed){error=t("请先安装快速 OCR 模型","Install the fast OCR model first");return;}if(regionEnabled&&!selection){error=t("请先在图片上拖拽框选识别区域","Drag on the image to select a recognition region first");return;}const token=tasks.begin();controller=new AbortController();busy=true;error="";progress=0;resultLines=[];status=t("准备原生 OCR…","Preparing native OCR…");try{const region=regionEnabled?normalizeOcrRectangle(selection,imageWidth,imageHeight):undefined;const result=await recognitionTasks.run(async task=>{task.check();return recognizeNativeOcr(file,{region,quality,enhance,smartCorrection,layout,signal:task.signal,onProgress:(update)=>{if(!tasks.isCurrent(token))return;status=progressLabel(update.stage);progress=update.progress;task.update({stage:update.stage,progress:Number(update.progress)/100});}});});if(!tasks.isCurrent(token))return;text=result.text||"";resultLines=Array.isArray(result.lines)?result.lines:[];confidence=Math.round((result.confidence||0)*10)/10;confidenceMin=Math.round((result.minimumConfidence||0)*10)/10;recognizedLines=Number(result.recognizedLines||0);status=t("识别完成","Recognition complete");progress=100;}catch(cause){if(tasks.isCurrent(token)){if(cause?.name==="AbortError"){status=t("已取消","Cancelled");progress=0;}else{error=imageInputError(cause,t);status="";}}}finally{if(tasks.isCurrent(token)){busy=false;controller=null;}}}
  function cancel(){recognitionTasks.cancel();tasks.cancel();controller?.abort();controller=null;busy=false;status=t("已取消","Cancelled");progress=0;}
  async function saveText(){if(!text)return;try{await saveBlobThroughHost(new Blob([text],{type:"text/plain;charset=utf-8"}),{fileName:`${file?.name?.replace(/\.[^.]+$/,"")||"ocr"}.txt`,mimeType:"text/plain",binary:true,title:t("保存识别文本","Save recognized text")});}catch(cause){error=localizeError(locale,cause);}}
  function sizeLabel(bytes){return `${(Number(bytes||0)/1024/1024).toFixed(1)} MB`;}
  function showModelNotice(message){if(modelNoticeTimer)clearTimeout(modelNoticeTimer);modelStatus=message;modelNoticeTimer=setTimeout(()=>{modelStatus="";modelNoticeTimer=null;},3000);}
  async function refreshModels(){try{models=await getOcrModelStatus();}catch(cause){error=localizeError(locale,cause);}}
  async function installTier(tier){if(modelBusy)return;if(modelNoticeTimer){clearTimeout(modelNoticeTimer);modelNoticeTimer=null;}const installController=new AbortController();modelInstallController=installController;modelBusy=true;modelCancelling=false;modelProgress=0;modelStatus=t("正在连接 GitHub Release…","Connecting to GitHub Release…");error="";try{await modelTasks.run(async task=>{task.check();return installOcrModels(tier,{signal:task.signal,onProgress:(update)=>{if(installController.signal.aborted||modelInstallController!==installController)return;modelSessionId=update.sessionId||modelSessionId;modelProgress=Math.round(Number(update.progress||0)*100);task.update({stage:"upload",progress:Number(update.progress||0)});modelStatus=update.stage==="download"?t(`正在下载 ${update.file||"OCR 模型"}`,`Downloading ${update.file||"OCR model"}`):t("正在准备下载…","Preparing download…");}});});await refreshModels();showModelNotice(t("模型安装完成","Model installation complete"));}catch(cause){if(cause?.name!=="AbortError"){error=localizeError(locale,cause);modelStatus="";}else showModelNotice(t("模型下载已取消","Model download cancelled"));}finally{if(modelInstallController===installController)modelInstallController=null;modelBusy=false;modelCancelling=false;modelSessionId="";}}
  async function cancelModelDownload(){if(modelCancelling)return;modelCancelling=true;const sessionId=modelSessionId;modelTasks.cancel();modelInstallController?.abort();try{if(sessionId)await cancelOcrModelInstall(sessionId);}catch(cause){error=localizeError(locale,cause);}finally{modelCancelling=false;}}
  async function removeTier(tier){if(pendingRemove!==tier){pendingRemove=tier;return;}try{await removeOcrModels(tier);pendingRemove="";if(tier==="base")quality="auto";else if(quality==="accurate")quality="auto";await refreshModels();}catch(cause){error=localizeError(locale,cause);}}
</script>

<div class="page">
  {#if models}
    <section class="model-card">
      <div class="model-summary">
        <div class="model-summary-copy"><strong>{t("OCR 本地模型","Local OCR models")}</strong><span>{t("快速模型","Fast model")}：{models.base?.installed?t("已安装","Installed"):models.base?.updateRequired?t("需要更新","Update required"):t("未安装","Not installed")} · {t("高精度","Accurate")}：{models.accurate?.installed?t("已安装","Installed"):models.accurate?.updateRequired?t("需要更新","Update required"):t("未安装","Not installed")}</span></div>
        <div class="model-summary-actions">{#if !modelBusy&&modelStatus}<span class="model-notice" role="status">{modelStatus}</span>{/if}<button class="dbx-btn" type="button" aria-expanded={modelPanelOpen} onclick={()=>modelPanelOpen=!modelPanelOpen}>{modelPanelOpen?t("收起","Collapse"):t("管理模型","Manage models")}</button></div>
      </div>
      {#if modelPanelOpen}
        <div class="model-details">
          <div class="model-copy"><span>{t("模型仅在你点击安装时从 GitHub Release 下载；校验 SHA-256 后保存在 DBX 插件数据目录，识别过程仍完全离线。","Models are downloaded from GitHub Release only after you click Install. They are SHA-256 verified, stored in DBX plugin data, and recognition remains fully offline.")}</span><small>{models.source} · {models.license} · {models.version}</small></div>
          <div class="model-tiers">
            <div class="model-tier"><span><b>{t("快速模型（推荐）","Fast model (recommended)")}</b><small>{sizeLabel(models.base?.size)} · {models.base?.installed?t("已安装","Installed"):models.base?.updateRequired?t("需要更新","Update required"):t("未安装","Not installed")}</small></span>{#if models.base?.installed}<button class="dbx-btn" type="button" disabled={modelBusy} onclick={()=>removeTier("base")}>{pendingRemove==="base"?t("再次点击确认删除全部模型","Click again to remove all models"):t("删除","Remove")}</button>{:else}<button class="dbx-btn dbx-btn--primary" type="button" disabled={modelBusy} onclick={()=>installTier("base")}>{models.base?.updateRequired?t("重新下载","Download again"):t("安装快速模型","Install fast model")}</button>{/if}</div>
            <div class="model-tier"><span><b>{t("高精度扩展","Accurate extension")}</b><small>{sizeLabel(models.accurate?.size)} · {models.accurate?.installed?t("已安装","Installed"):models.accurate?.updateRequired?t("需要更新","Update required"):t("可选下载","Optional")}</small></span>{#if models.accurate?.installed}<button class="dbx-btn" type="button" disabled={modelBusy} onclick={()=>removeTier("accurate")}>{pendingRemove==="accurate"?t("再次点击确认删除","Click again to confirm"):t("删除","Remove")}</button>{:else}<button class="dbx-btn" type="button" disabled={modelBusy} onclick={()=>installTier("accurate")}>{models.accurate?.updateRequired?t("重新下载","Download again"):t("安装高精度模型","Install accurate model")}</button>{/if}</div>
          </div>
        </div>
      {/if}
      {#if modelBusy}<div class="model-progress" role="status"><div style={`width:${modelProgress}%`}></div><span>{modelStatus}{modelProgress?` · ${modelProgress}%`:""}</span><button class="dbx-btn" type="button" disabled={modelCancelling} onclick={cancelModelDownload}>{t("取消下载","Cancel download")}</button></div>{/if}
    </section>
  {/if}
  <div class="toolbar"><label class="dbx-btn file">{file?t("更换图片","Replace image"):t("选择图片","Choose image")}<input type="file" accept="image/png,image/jpeg,image/webp,image/bmp" onchange={onFile}/></label><div class="ocr-options"><label class="quality"><span>{t("识别质量","Recognition quality")}</span><Select bind:value={quality} options={qualityOptions} disabled={!models?.base?.installed||modelBusy} ariaLabel={t("识别质量","Recognition quality")} /></label><label class="region-toggle" title={t("仅建议用于低对比度、轻微模糊的文档；清晰图片通常无需开启","Recommended for low-contrast or slightly blurred documents only")}><input type="checkbox" checked={enhance} onchange={(event)=>enhance=event.currentTarget.checked}/>{t("低对比度增强","Low-contrast enhancement")}</label><label class="region-toggle" title={t("只纠正通过校验规则的易混淆字符，不会补充未识别字段","Only fixes ambiguous characters when validation succeeds; never invents fields")}><input type="checkbox" checked={smartCorrection} onchange={(event)=>smartCorrection=event.currentTarget.checked}/>{t("校验型字符纠错","Validated character correction")}</label><label class="region-toggle" title={t("只按检测位置合并同行文本，不改变识别字符","Only arranges detected text by position; it does not change characters")}><input type="checkbox" checked={layout} onchange={(event)=>layout=event.currentTarget.checked}/>{t("按视觉位置排版","Arrange by visual position")}</label><label class="region-toggle"><input type="checkbox" checked={regionEnabled} onchange={toggleRegion}/>{t("仅识别区域","Recognize region only")}</label>{#if resultLines.length}<label class="region-toggle"><input type="checkbox" checked={showBoxes} onchange={(event)=>showBoxes=event.currentTarget.checked}/>{t("显示识别框","Show boxes")}</label>{/if}{#if text}<button class="dbx-btn" type="button" onclick={saveText}>{t("保存文本","Save text")}</button>{/if}{#if busy}<button class="dbx-btn" type="button" onclick={cancel}>{t("取消","Cancel")}</button>{/if}<button class="dbx-btn dbx-btn--primary" type="button" onclick={recognize} disabled={!file||busy||!models?.base?.installed}>{busy?t("识别中…","Recognizing…"):t("开始识别","Recognize")}</button></div></div>
  {#if regionEnabled&&file}<div class="region-hint"><span>{selection?t(`已框选 ${selection.width} × ${selection.height}px`,`Selected ${selection.width} × ${selection.height}px`):t("在图片上拖拽框选识别区域","Drag on the image to select a recognition region")}</span>{#if selection}<button class="dbx-btn" type="button" onclick={()=>selection=null}>{t("重新框选","Reselect")}</button>{/if}</div>{/if}
  {#if !file}<label class="drop file-button">{t("安装模型后，选择中英文图片进行完全离线识别","After installing a model, choose a Chinese or English image for fully offline recognition")}<input type="file" accept="image/png,image/jpeg,image/webp,image/bmp" onchange={onFile}/></label>{:else}<div class="workspace"><section class="preview"><div role="presentation" class:selecting={regionEnabled} class="image-stage" bind:this={imageStage} onpointerdown={startSelection} onpointermove={moveSelection} onpointerup={finishSelection} onpointercancel={finishSelection}><img src={sourceUrl} alt={file.name} draggable="false"/>{#if showBoxes}{#each resultLines as line}<div class="ocr-box" class:uncertain={line.confidence<70} style={boxStyle(line.bounds)} title={`${line.text} · ${Math.round(line.confidence)}%`}></div>{/each}{/if}{#if regionEnabled&&selection}<div class="selection" style={selectionStyle()}><span>{selection.width} × {selection.height}</span></div>{/if}</div></section><section class="result"><div class="result-head"><span>{confidence==null?t("识别文本","Recognized text"):`${t("模型置信参考（非准确率）","Model confidence reference (not accuracy)")} ${confidence}%${recognizedLines?` · ${recognizedLines}${t(" 行"," lines")}`:""}${confidenceMin!=null?` · ${t("最低字符","lowest character")} ${confidenceMin}%`:""}`}</span><CopyButton {locale} getText={()=>text}/></div><textarea class="dbx-textarea" value={text} readonly placeholder={t("识别结果将显示在这里","Recognition result will appear here")}></textarea></section></div>{/if}
  {#if status}<div class="progress" role="status"><div style={`width:${progress}%`}></div><span>{status} {progress ? `${progress}%` : ""}</span></div>{/if}{#if error}<div class="error" role="alert">{error}</div>{/if}
</div>

<style>
  .model-card{display:grid;gap:10px;padding:8px 10px;border:1px solid var(--color-border);border-radius:10px;background:var(--color-card)}.model-summary{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:32px}.model-summary-copy{display:flex;align-items:baseline;gap:12px;min-width:0}.model-summary-copy span{overflow:hidden;color:var(--color-muted-foreground);font-size:12px;text-overflow:ellipsis;white-space:nowrap}.model-summary-actions{display:flex;flex:0 0 auto;align-items:center;gap:8px}.model-notice{max-width:220px;overflow:hidden;padding:4px 8px;border-radius:999px;background:color-mix(in srgb,var(--color-primary) 9%,var(--color-muted));color:var(--color-primary);font-size:11px;font-weight:600;text-overflow:ellipsis;white-space:nowrap}.model-details{display:grid;grid-template-columns:minmax(230px,1fr) minmax(340px,1.35fr);gap:12px;padding-top:10px;border-top:1px solid var(--color-border)}.model-copy{display:flex;flex-direction:column;gap:5px}.model-copy span,.model-copy small,.model-tier small{color:var(--color-muted-foreground);font-size:12px;line-height:1.45}.model-tiers{display:grid;gap:8px}.model-tier{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px;border:1px solid var(--color-border);border-radius:8px}.model-tier>span{display:flex;flex-direction:column;gap:3px}.model-progress{position:relative;display:flex;align-items:center;justify-content:space-between;min-height:32px;overflow:hidden;padding:5px 8px;border-radius:7px;background:var(--color-muted)}.model-progress>div{position:absolute;inset:0 auto 0 0;background:color-mix(in srgb,var(--color-primary) 18%,transparent)}.model-progress span,.model-progress button{position:relative}
  .toolbar{align-items:center;flex-wrap:wrap}.ocr-options{display:flex;align-items:center;justify-content:flex-end;gap:8px;flex-wrap:wrap}.quality{display:flex;align-items:center;gap:6px;font-size:12px}.quality :global(.dbx-custom-select){width:auto;min-width:126px}.region-toggle{display:flex;align-items:center;gap:6px;font-size:12px}.region-hint{display:flex;min-height:36px;align-items:center;justify-content:space-between;gap:12px;padding:6px 10px;border:1px solid color-mix(in srgb,var(--color-primary) 35%,var(--color-border));border-radius:8px;background:color-mix(in srgb,var(--color-primary) 7%,var(--color-card));color:var(--color-muted-foreground);font-size:12px}.region-hint .dbx-btn{min-height:28px;height:28px}
  .page{display:flex;flex:1;min-height:0;flex-direction:column;gap:12px}.toolbar{display:flex;justify-content:space-between;gap:8px}.file,.drop{position:relative;overflow:hidden}.file input,.drop input{position:absolute;inset:0;opacity:0}.drop{display:grid;flex:1;min-height:300px;place-items:center;border:1px dashed var(--color-border);border-radius:12px;color:var(--color-muted-foreground)}.workspace{display:grid;grid-template-columns:1fr 1fr;gap:12px;flex:1;min-height:0}.workspace>section{min-height:360px;border:1px solid var(--color-border);border-radius:10px}.preview{display:grid;place-items:center;overflow:auto;padding:8px;background:var(--color-muted)}.image-stage{position:relative;display:inline-block;max-width:100%;max-height:100%;line-height:0;user-select:none}.image-stage.selecting{cursor:crosshair;touch-action:none}.preview img{display:block;max-width:100%;max-height:calc(100vh - 230px);object-fit:contain;pointer-events:none}.selection{position:absolute;box-sizing:border-box;border:2px solid var(--color-primary);background:color-mix(in srgb,var(--color-primary) 12%,transparent);box-shadow:0 0 0 9999px color-mix(in srgb,#000 30%,transparent);pointer-events:none}.selection span{position:absolute;right:-2px;bottom:100%;padding:3px 6px;border-radius:5px 5px 0 0;background:var(--color-primary);color:var(--color-primary-foreground);font:11px/1.3 var(--font-mono);white-space:nowrap}.result{display:flex;flex-direction:column;padding:12px}.result-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;font-size:12px}.result textarea{flex:1;resize:none}.progress{position:relative;overflow:hidden;min-height:28px;border-radius:7px;background:var(--color-muted)}.progress>div{position:absolute;inset:0 auto 0 0;background:color-mix(in srgb,var(--color-primary) 18%,transparent)}.progress span{position:relative;display:block;padding:6px 9px;font-size:12px}.error{color:var(--color-destructive);font-size:12px}@media(max-width:760px){.workspace{grid-template-columns:1fr}}
  .ocr-box{position:absolute;box-sizing:border-box;border:1px solid var(--color-success);background:var(--color-success-bg);pointer-events:none}.ocr-box.uncertain{border-color:var(--color-warning);background:var(--color-warning-bg)}@media(max-width:760px){.model-details{grid-template-columns:1fr}.model-summary-copy{align-items:flex-start;flex-direction:column;gap:2px}}
</style>
